import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, Switch,Spa } from "@heroui/react";
import { Loading } from '../../../components';
import { useFormik } from "formik";
import useApi from "../../../hooks/useApi";
import makeAnimated from "react-select/animated"
import CreateSelect from "react-select/creatable";
import { ToastContainer, toast } from "react-toastify";
import transportApi from "../../../api/transport/transportApi";
import { DatePicker, Space, TimePicker } from 'antd';
import moment from 'moment';


export default function CrewMemberFormModal({ openEditModal, setopenEditModal, item, updated, setUpdated, modalTitle }) {
    // const { isOpen, onOpen, onOpenChange } = useDisclosure();
    const animatedComponent = makeAnimated();
    const [trip, setTrip] = useState(item ? item : null)

    console.log("Item at modal", item)
    console.log("Item at trip", trip)
    const dateFormat = 'YYYY-MM-DD';
    const timeFormat = 'HH:mm';

    const [switchLabel, setswitchLabel] = useState("Activate")
    const [switchStatus, setswitchStatus] = useState(item && item.is_active === 'true' ? true : false)

    const [routes, setRoutes] = useState([])
    const getRoutesActionsApi = useApi(transportApi.transportAction)
    const getVehiclesActionsApi = useApi(transportApi.transportAction)
    const transportActionsApi = useApi(transportApi.transportAction)
    const getRoutes = async () => {
        await getRoutesActionsApi.request({
            "action": "GetEntityRoutes"

        })
    }
    const getVehicles = async () => {
        await getVehiclesActionsApi.request({
            "action": "GetEntityVehicles"

        })
    }

    useEffect(() => {
        getRoutes()
        getVehicles()
    }, [])

    useEffect(() => {

        if (getRoutesActionsApi.data && getRoutesActionsApi.data.length) {

            setRoutes(getRoutesActionsApi.data.map((i) => ({ label: i.title, value: i.id })))
        }

        console.log
            ('getRoutesActionsApi.data', getRoutesActionsApi.data)
    }, [getRoutesActionsApi.data])
    useEffect(() => {

        if (getVehiclesActionsApi.data && getVehiclesActionsApi.data.length) {

            setTrips(getVehiclesActionsApi.data.map((i) => ({ label: i.registration, value: i.id })))
        }

        console.log
            ('getVehiclesActionsApi.data', getVehiclesActionsApi.data)
    }, [getVehiclesActionsApi.data])

    const [errors, setErrors] = useState();





    const handleVehicleAction = async (data) => {
        console.log("data at", data
        )
        const result = await transportActionsApi.request(data);

        if (result.ok) {
            console.log("res", result)
            setUpdated(true)
            setopenEditModal(false)
        } else {
            setUpdated(false)
        }

    }

    useEffect(() => { }, [trip])

    useEffect(() => {

        if (transportActionsApi.data) {
            setopenEditModal(false)
            // if (transportActionsApi.data.destination) {
            //     setDestination(transportActionsApi.data.destination)
            // }

            if (transportActionsApi.data.errors) {
                setErrors(transportActionsApi.data.errors)
            }
        }



        console.log("transportActionsApi.data", transportActionsApi.data)
    }, [transportActionsApi.data])

    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);

    const formik = useFormik({
        initialValues: {
            route: trip ? { 'label': trip.route_title, 'value': trip.route } : '',
            vehicle: trip ? { 'label': trip.vehicle_registration, 'value': trip.vehicle } : '',
            departure_time: trip ? trip.departure_time : '',
            departure_date: trip ? trip.departure_date : '',
            is_active: trip ? trip.is_active : 'false',
        },

        validationSchema: Yup.object({
            vehicle: Yup.object().required("Vehicle is required"),
            route: Yup.object().required("Route is required"),
            departure_date: Yup.string().required("Departure date is required"),
            departure_time: Yup.string().required("Departure time is required"),
            is_active: Yup.bool().label('Status')
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log('VALZ', values)
            setErrors([])

            if (item) {

                handleVehicleAction({
                    "action": "UpdateTrip",
                    "trip_details": {
                        "trip_id": item.id,
                        "route": values.route.value,
                        "vehicle": values.vehicle.value,
                        "departure_time": values.departure_time,
                        "departure_date": values.departure_date,
                        "is_active": values.is_active,
                    }
                })
            } else {
                handleVehicleAction({
                    "action": "CreateTrip",
                    "trip_details": {

                        "vehicle": values.vehicle.value,
                        "route": values.route.value,
                        "departure_time": values.departure_time,
                        "departure_date": values.departure_date,
                        "is_active": values.is_active,
                    }
                })
            }




            // resetForm();
        },
    });


    const searchVehicles = async (data) => {
        await transportActionsApi.request(data);
    };

    const [vehicles, setTrips] = useState([]);

    // useEffect(() => {
    //     if (transportActionsApi.data) {
    //         if (transportActionsApi.data.length) {
    //             setTrips(transportActionsApi.data);
    //         }
    //     }
    //     console.log("transportActionsApi.data", transportActionsApi.data);
    // }, [transportActionsApi.data]);
    const handleChange = (date, dateArray) => {
        // setSelectedDates(dateArray);
        console.log("Date", date)
        console.log("Date Arra", dateArray)
        formik.setFieldValue("departure_date", dateArray)
    };

    const handleSwitchChange = (e) => {
        setswitchStatus(e.target.checked === true)
        if (e.target.checked === true) {
            formik.setFieldValue('is_active', 'true')
            setswitchLabel("Deactivate")

        } else if (e.target.checked === false) {
            formik.setFieldValue('is_active', 'false')
            setswitchLabel("Activate")
        } else {
            formik.setFieldValue('is_active', '')
        }

        console.log('eee', e.target.checked)
    }


    const handleTimeChange = (timeArray, time) => {
        formik.setFieldValue("departure_time", time)
    }
    return (
        <>

            <Modal
                isOpen={openEditModal}
                placement="center"
            >
                <ModalContent>


                    {(onClose) => (
                        <>
                            <ToastContainer position="bottom-center" theme="colored" />

                            {transportActionsApi.loading ? <Loading /> : <form className="items-center grid grid-cols-1"
                                onSubmit={formik.handleSubmit}
                            > <ModalHeader className="flex flex-col gap-1">{modalTitle}</ModalHeader>
                                <ModalBody>
                                    <p>Select vehicle</p>
                                    <div>
                                        <CreateSelect
                                            styles={{
                                                control: (baseStyles, state) => ({
                                                    ...baseStyles,
                                                    borderColor: state.isFocused ? 'black' : 'grey',
                                                    height: '56px',
                                                    borderRadius: '20px',
                                                }),
                                            }}
                                            id="vehicle"
                                            key="vehicle"
                                            name="vehicle"
                                            components={animatedComponent}
                                            placeholder="Select vehicle"
                                            isClearable
                                            value={formik.values.vehicle}
                                            onChange={(value) => formik.setFieldValue("vehicle", value)}
                                            options={vehicles}
                                        />
                                        {formik.touched.vehicle && formik.errors.vehicle ? (
                                            <p className="text-red-500 text-sm">{formik.errors.vehicle}</p>
                                        ) : null}
                                    </div>
                                    <p>Select route</p>
                                    <div>
                                        <CreateSelect
                                            styles={{
                                                control: (baseStyles, state) => ({
                                                    ...baseStyles,
                                                    borderColor: state.isFocused ? 'black' : 'grey',
                                                    height: '56px',
                                                    borderRadius: '20px',
                                                }),
                                            }}
                                            id="route"
                                            key="route"
                                            name="route"
                                            components={animatedComponent}
                                            placeholder="Select route"
                                            isClearable
                                            value={formik.values.route}
                                            onChange={(value) => formik.setFieldValue("route", value)}
                                            options={routes}
                                        />
                                        {formik.touched.route && formik.errors.route ? (
                                            <p className="text-red-500 text-sm">{formik.errors.route}</p>
                                        ) : null}
                                    </div>
                                    <div>
                                        <p>Select departure date</p>

                                    </div>
                                    <DatePicker id="departure_date" name="departure_date" onChange={handleChange} defaultValue={moment(new Date(), dateFormat)} format={dateFormat} />

                                    <div>
                                        <p>Select departure time</p>

                                    </div>
                                    <TimePicker id="departure_time" name="departure_time" onChange={handleTimeChange} defaultValue={moment('12:08', timeFormat)} format={timeFormat} />
                                    <Space>
                                    <Switch id="is_active" name="is_active" value={formik.values.is_active} isSelected={switchStatus} onChange={(e) => handleSwitchChange(e)} defaultSelected size="md">{switchLabel}</Switch>
                                </Space>
                                    </ModalBody>
                                <ModalFooter>
                                    <Button color="danger" variant="flat" onPress={() => setopenEditModal(false)}>
                                        Cancel
                                    </Button>
                                    <Button color="primary" type="submit" onPress={onClose}>
                                        Save
                                    </Button>
                                </ModalFooter>

                            </form>}


                        </>
                    )}
                </ModalContent>
            </Modal>
        </>
    );
}
